import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.ClientStartItemCooldown{Category: "minecraft:shield", Duration: 300}
SHIELD = bytes.fromhex("106d696e6563726166743a736869656c64d804")

# generated by gophertunnel b8bd735:
# &packet.ClientStartItemCooldown{Category: "", Duration: -1}
NEGATIVE = bytes.fromhex("0001")

# generated by gophertunnel b8bd735:
# &packet.ClientStartItemCooldown{Category: strings.Repeat("a", 200), Duration: 1}
LONG_CATEGORY = bytes.fromhex(
    ""
)

GOLDENS = [
    pytest.param(
        v2225.PlayerStartItemCooldownPacket(item_category="minecraft:shield", duration_ticks=300), SHIELD, id="shield"
    ),
    pytest.param(
        v2225.PlayerStartItemCooldownPacket(item_category="", duration_ticks=-1), NEGATIVE, id="negative-duration"
    ),
    pytest.param(
        v2225.PlayerStartItemCooldownPacket(item_category="a" * 200, duration_ticks=1),
        LONG_CATEGORY,
        id="long-category",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_player_start_item_cooldown_is_packet_176(version):
    assert version.packets[176] is version.PlayerStartItemCooldownPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_start_item_cooldown_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_start_item_cooldown_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
